import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const DEFAULT_DATA_FILE = join(dirname(fileURLToPath(import.meta.url)), '..', 'data', 'books.json');

// Overridable via env so tests can point at a throwaway file instead of the real data.
function getDataFile() {
  return process.env.BOOKS_DATA_FILE || DEFAULT_DATA_FILE;
}

async function load() {
  const file = getDataFile();
  await mkdir(dirname(file), { recursive: true });
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function save(books) {
  await writeFile(getDataFile(), JSON.stringify(books, null, 2));
}

export async function getAllBooks() {
  return load();
}

export async function getBook(id) {
  const books = await load();
  return books.find((b) => b.id === id);
}

export async function addBook({ title, author, notes }) {
  const books = await load();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes || '').trim(),
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await save(books);
  return book;
}

export async function markFinished(id) {
  const books = await load();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  await save(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await load();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = notes;
  await save(books);
  return book;
}

