import express from 'express';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { getAllBooks, getBook, addBook, markFinished, updateNotes } from './lib/store.js';

const __dirname = dirname(fileURLToPath(import.meta.url));

const app = express();
app.set('view engine', 'ejs');
app.set('views', join(__dirname, 'views'));
app.use(express.urlencoded({ extended: true }));
app.use(express.static(join(__dirname, 'public')));

app.get('/', async (req, res) => {
  const books = await getAllBooks();
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => new Date(b.addedAt) - new Date(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => new Date(b.finishedAt) - new Date(a.finishedAt));
  res.render('index', { reading, finished });
});

app.get('/books/new', (req, res) => {
  res.render('new', { error: null });
});

app.post('/books', async (req, res) => {
  const { title, author, notes } = req.body;
  if (!title?.trim() || !author?.trim()) {
    return res.status(400).render('new', { error: 'Title and author are required.' });
  }
  const book = await addBook({ title, author, notes });
  res.redirect(`/books/${book.id}`);
});

app.get('/books/:id', async (req, res) => {
  const book = await getBook(req.params.id);
  if (!book) return res.status(404).send('Book not found');
  res.render('book', { book });
});

app.post('/books/:id/finish', async (req, res) => {
  await markFinished(req.params.id);
  res.redirect(`/books/${req.params.id}`);
});

app.post('/books/:id/notes', async (req, res) => {
  await updateNotes(req.params.id, req.body.notes || '');
  res.redirect(`/books/${req.params.id}`);
});

