import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import * as store from '../lib/store.js';

let dir;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'books-'));
  process.env.BOOKS_DATA_FILE = join(dir, 'books.json');
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
  delete process.env.BOOKS_DATA_FILE;
});

describe('book store', () => {
  it('starts empty', async () => {
    expect(await store.getAllBooks()).toEqual([]);
  });

  it('adds a book as currently reading', async () => {
    const book = await store.addBook({ title: 'Dune', author: 'Frank Herbert', notes: '' });
    expect(book.status).toBe('reading');
    expect(book.title).toBe('Dune');
    expect(await store.getAllBooks()).toHaveLength(1);
  });

  it('marks a book finished', async () => {
    const book = await store.addBook({ title: 'Dune', author: 'Frank Herbert' });
    const finished = await store.markFinished(book.id);
    expect(finished.status).toBe('finished');
    expect(finished.finishedAt).toBeTruthy();
  });

  it('returns null when finishing an unknown id', async () => {
    expect(await store.markFinished('nope')).toBeNull();
  });

  it('updates notes', async () => {
    const book = await store.addBook({ title: 'Dune', author: 'Frank Herbert' });
    const updated = await store.updateNotes(book.id, 'Great worldbuilding');
    expect(updated.notes).toBe('Great worldbuilding');
  });

  it('fetches a single book by id', async () => {
    const book = await store.addBook({ title: 'Dune', author: 'Frank Herbert' });
    expect((await store.getBook(book.id)).title).toBe('Dune');
    expect(await store.getBook('nope')).toBeUndefined();
  });

  it('persists across separate loads', async () => {
    await store.addBook({ title: 'Dune', author: 'Frank Herbert' });
    await store.addBook({ title: 'Hyperion', author: 'Dan Simmons' });
    expect(await store.getAllBooks()).toHaveLength(2);
  });
});

